const data = $input.all()[0].json;
const ORIGIN = 'https://brazil.nothingprojector.com';

// A API exige URLs http(s) completas; o site devolve "/products/..." e "//cdn...".
const toAbsolute = (value) => {
    if (!value) return undefined;
    if (/^https?:\/\//i.test(value)) return value;
    if (value.startsWith('//')) return 'https:' + value;
    return ORIGIN + (value.startsWith('/') ? value : '/' + value);
};

// O nó HTML anexa o href ao texto ("Nome [/products/...]") e mantém as quebras de linha.
const cleanName = (value) =>
    (value ?? '').replace(/\[\/[^\]]*\]/g, '').replace(/\s+/g, ' ').trim();

const decode = (value) => value
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');

const toText = (html) => decode(
    (html ?? '')
        .replace(/<svg[\s\S]*?<\/svg>/gi, '')
        .replace(/<br\s*\/?>/gi, ' · ')
        .replace(/<[^>]+>/g, ' ')
).replace(/\s+/g, ' ').trim();

const match = (html, regex) => (html.match(regex) ?? [])[1];

// Monta a descrição a partir do bloco .product-card__info: destaques do card
// (brinde, estoque, preço, envio) e a ficha técnica ("Marca: ...", "Resolução: ...").
// Ficam de fora o título (já é o name) e o selo de avaliações oculto.
const buildDescription = (html) => {
    if (!html) return undefined;
    const lines = [];

    const free = toText(match(html, /product-card__free_text[^>]*>([\s\S]*?)<\/div>/));
    if (free) lines.push(free);

    const stock = toText(match(html, /product-card__importa[^>]*>([\s\S]*?)<\/div>/));
    if (stock) lines.push(stock);

    // Cada preço (<sale-price>, <compare-at-price>) traz o rótulo num span sr-only.
    const priceHtml = match(html, /<price-list[^>]*>([\s\S]*?)<\/price-list>/) ?? '';
    for (const [, tag] of priceHtml.matchAll(/<([a-z-]+-price)[^>]*>[\s\S]*?<\/\1>/g)) {
        const block = match(priceHtml, new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`));
        const label = toText(match(block, /<span class="sr-only">([\s\S]*?)<\/span>/)) || 'Preço';
        const price = toText(block.replace(/<span class="sr-only">[\s\S]*?<\/span>/g, ''));
        if (price) lines.push(`${label}: ${price}`);
    }

    const dispatch = toText(match(html, /product-dispatch[^>]*>([\s\S]*?)<\/div>/));
    if (dispatch) lines.push(dispatch);

    for (const [, item] of html.matchAll(/<div class="item">([\s\S]*?)<\/div>/g)) {
        const spans = [...item.matchAll(/<span[^>]*>([\s\S]*?)<\/span>/g)].map(([, s]) => toText(s));
        const [label, value] = [spans[0], spans.slice(1).join(' ')];
        if (label && value) lines.push(`${label}: ${value.replace(/\s*:\s*/g, ':')}`);
    }

    return lines.length ? lines.join('\n') : undefined;
};

const result = data.name.map((name, index) => ({
    name: cleanName(name),
    description: buildDescription(data.info?.[index]),
    price: data.price[index],
    url: toAbsolute(data.url[index]),
    image: toAbsolute(data.image[index]),
}));

return result.map(item => ({
    json: item
}));

// Compara pelo externalLink, ignorando espaços e barra final.
const normalize = (link) => (link ?? '').trim().replace(/[/]+$/, '');

// A API devolve um array por página; o n8n entrega cada produto como um item.
const existingLinks = new Set(
    $input.all().map((item) => normalize(item.json.externalLink)).filter(Boolean)
);

const seen = new Set(existingLinks);
const novos = [];
for (const item of $('Code in JavaScript').all()) {
    const link = normalize(item.json.url);
    if (!link || seen.has(link)) continue;
    seen.add(link);
    novos.push({ json: item.json });
}

return novos;
